package com.amsha.rag;

import java.util.List;

/**
 * Port interface for reranking candidate chunks.
 * <p>
 * Implementations (such as local ONNX cross-encoders or remote scoring models)
 * compute model-local relevance scores for a list of candidate chunks against a query.
 * Upstream types (such as LangChain4j ScoringModel) remain strictly adapted behind this port.
 */
public interface RerankerPort {

    /**
     * Reranks the candidate chunks against the given query.
     *
     * @param query      the search query
     * @param candidates the candidate chunks generated by FTS5/BM25 and vector search
     * @return the reranked chunks sorted by model-local rerank score descending
     */
    List<RerankedChunk> rerank(String query, List<ScoredChunk> candidates);
}
